INSERT OR REPLACE INTO ig_reel (shortcode, run_id, account, url, caption, posted_at, duration_s, billed_minutes, views, likes, comments, video_url, collected_via) VALUES ('Dch4L4tEl9p', 'hedge.sphere.ai@2026-08-29T08:47:21Z', 'hedge.sphere.ai', 'https://www.instagram.com/p/Dch4L4tEl9p/', '💡 萌寵品牌必看！用 AI 輕鬆打造超吸睛寵物用品宣傳片

📌 核心製作步驟
一、使用 LTX Studio 建立基礎框架：開啟 LTX Studio，專注於元素、構圖和色彩三個關鍵點，利用提示詞讓畫面保持風格一致。

二、上傳產品與模特兒生成圖像：點擊圖像生成並上傳寵物與產品圖片，接著利用比例模型與色彩方案（如直接描述色彩或上傳色板）讓系統跟著走。

三、加入 Storyboard 與 Midjourney 動態生成：將所有畫面加入 Storyboard 查看整體感覺，也可以將生成的圖片匯入 Midjourney 來生成動態影片。

看完是不是覺得用 AI 做寵物廣告變得超簡單又有趣？
你家也有毛小孩嗎？你最想幫牠穿上什麼風格的 AI 潮衣呢？

